package pe.marcona.mtc.util;

public final class ImageAssets {
    private ImageAssets() {
        // Clase de utilería
    }

    // Segmentos estructurados para cumplir con la especificación de la JVM (JVMS §4.4.7 límite de 65535 bytes por literal)
    private static final String[] CHUNKS = new String[] {
        "data:image/png;base64,",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    };

    // Logo del municipio en Base64 para inyección directa en reportes PDF o respuestas API
    public static final String MARCONA_ESCUDO_BASE64 = String.join("", CHUNKS);
}

